1#include <Servo.h>

// Cria os objetos para os 4 servomotores
Servo servo1;
Servo servo2;
Servo servo3;
Servo servo4;

// Define os pinos digitais do Arduino Nano conectados aos sinais dos servos
const int pinoServo1 = 6;
const int pinoServo2 = 8;
const int pinoServo3 = 10;
const int pinoServo4 = 12;

void setup() {
  // Associa cada objeto ao seu respectivo pino
    servo1.attach(pinoServo1);
      servo2.attach(pinoServo2);
        servo3.attach(pinoServo3);
          servo4.attach(pinoServo4);
          }

          void loop() {
            // Move todos os servos para 0 graus
              servo1.write(0);
                servo2.write(0);
                  servo3.write(0);
                    servo4.write(0);
                      delay(1000);

                        // Move todos os servos para 90 graus (posição central)
                          servo1.write(90);
                            servo2.write(90);
                              servo3.write(90);
                                servo4.write(90);
                                  delay(1000);

                                    // Move todos os servos para 180 graus
                                      servo1.write(180);
                                        servo2.write(180);
                                          servo3.write(180);
                                            servo4.write(180);
                                              delay(1000);
                                              }
